PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          username TEXT UNIQUE NOT NULL,
          password TEXT NOT NULL,
          full_name TEXT NOT NULL,
          role TEXT DEFAULT 'vendedor',
          active INTEGER DEFAULT 1,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE products (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          sku TEXT UNIQUE NOT NULL,
          ean13 TEXT UNIQUE,
          name TEXT NOT NULL,
          category TEXT NOT NULL,
          description TEXT,
          purchase_price REAL NOT NULL,
          sale_price REAL NOT NULL,
          stock INTEGER DEFAULT 0,
          min_stock INTEGER DEFAULT 10,
          supplier TEXT,
          expiration_date DATE,
          active INTEGER DEFAULT 1,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE category_coefficients (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        category TEXT UNIQUE NOT NULL,
        coefficient REAL DEFAULT 1.0
      );
CREATE TABLE cash_sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      date DATE UNIQUE NOT NULL,
      opening_amount REAL NOT NULL,
      closing_amount REAL,
      total_income REAL DEFAULT 0,
      total_expense REAL DEFAULT 0,
      carried_balance REAL DEFAULT 0,
      closed INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , closed_at TEXT);
CREATE TABLE cash_movements (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id INTEGER NOT NULL,
      type TEXT CHECK(type IN ('ingreso','egreso')) NOT NULL,
      concept TEXT NOT NULL,
      amount REAL NOT NULL,
      payment_method TEXT,
      user_id INTEGER,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (session_id) REFERENCES cash_sessions(id),
      FOREIGN KEY (user_id) REFERENCES users(id)
    );
CREATE TABLE sale_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sale_id INTEGER NOT NULL,
        product_id INTEGER NOT NULL,
        product_name TEXT NOT NULL,
        quantity REAL NOT NULL,
        unit_price REAL NOT NULL,
        subtotal REAL NOT NULL, discount REAL DEFAULT 0, discount_type TEXT DEFAULT 'percentage',
        FOREIGN KEY (sale_id) REFERENCES "sales_backup"(id) ON DELETE CASCADE,
        FOREIGN KEY (product_id) REFERENCES products(id)
      );
CREATE TABLE sales (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            subtotal REAL NOT NULL,
            tax REAL NOT NULL,
            total REAL NOT NULL,
            payment_method TEXT DEFAULT 'efectivo',
            created_at DATETIME NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users(id)
          );
CREATE TABLE refunds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sale_id INTEGER NOT NULL,
            reason TEXT,
            subtotal REAL NOT NULL,
            tax REAL NOT NULL,
            total REAL NOT NULL,
            created_at DATETIME NOT NULL,
            FOREIGN KEY (sale_id) REFERENCES sales(id)
          );
CREATE TABLE refund_items (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          refund_id INTEGER NOT NULL,
          product_id INTEGER NOT NULL,
          product_name TEXT NOT NULL,
          quantity REAL NOT NULL DEFAULT 0,
          unit_price REAL NOT NULL DEFAULT 0,
          subtotal REAL NOT NULL DEFAULT 0,
          FOREIGN KEY (refund_id) REFERENCES refunds(id) ON DELETE CASCADE,
          FOREIGN KEY (product_id) REFERENCES products(id)
        );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_products_ean13 ON products(ean13);
CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_coeff_category ON category_coefficients(category);
CREATE INDEX idx_sales_date ON sales(created_at);
COMMIT;
